from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        seg = [0] * (2 * size)

        for i, capacity in enumerate(baskets):
            seg[size + i] = capacity

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[(i << 1) | 1])

        unplaced = 0

        for fruit in fruits:
            if seg[1] < fruit:
                unplaced += 1
                continue

            node = 1
            while node < size:
                left = node << 1
                if seg[left] >= fruit:
                    node = left
                else:
                    node = left | 1

            seg[node] = 0
            node >>= 1

            while node:
                seg[node] = max(seg[node << 1], seg[(node << 1) | 1])
                node >>= 1

        return unplaced
