def is_simple_power(x, n):
    if x == 1:
        return True
    if n == 1:
        return False
    if n == 0:
        return x == 0
    if n == -1:
        return x == -1

    if n > 0:
        if x < 1:
            return False
        while x > 1:
            if x % n != 0:
                return False
            x //= n
        return True

    if x == 0:
        return False

    base = -n
    target = abs(x)
    if target == 1:
        return x == 1

    exponent = 0
    while target > 1:
        if target % base != 0:
            return False
        target //= base
        exponent += 1

    if x > 0:
        return exponent % 2 == 0
    return exponent % 2 == 1
