def is_samepatterns(sequence, patterns):
    """
    Return True if `sequence` follows the same equality pattern as `patterns`.

    That is:
    - positions with the same pattern element must have the same sequence value
    - positions with different pattern elements must have different sequence values
    """
    if len(sequence) != len(patterns):
        return False

    pattern_to_value = {}
    value_to_pattern = {}

    for value, pattern in zip(sequence, patterns):
        if pattern in pattern_to_value:
            if pattern_to_value[pattern] != value:
                return False
        else:
            pattern_to_value[pattern] = value

        if value in value_to_pattern:
            if value_to_pattern[value] != pattern:
                return False
        else:
            value_to_pattern[value] = pattern

    return True


assert is_samepatterns(["red", "green", "green"], ["a", "b", "b"]) == True
