from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)

        # first[value] = smallest index j such that elements[j] == value, or -1 if absent
        first = [-1] * (max_group + 1)
        present_values = []

        for idx, value in enumerate(elements):
            if value <= max_group and first[value] == -1:
                first[value] = idx
                present_values.append(value)

        # best[group_value] = smallest element index that can be assigned to a group of this value
        best = [-1] * (max_group + 1)

        for value in present_values:
            idx = first[value]
            for multiple in range(value, max_group + 1, value):
                current = best[multiple]
                if current == -1 or idx < current:
                    best[multiple] = idx

        return [best[group] for group in groups]
