def minPath(grid, k):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])
    if cols == 0:
        return []

    min_value = None
    min_pos = (0, 0)
    for r in range(rows):
        row = grid[r]
        for c, value in enumerate(row):
            if min_value is None or value < min_value:
                min_value = value
                min_pos = (r, c)

    if k <= 0:
        return []

    r, c = min_pos
    second_value = None
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            value = grid[nr][nc]
            if second_value is None or value < second_value:
                second_value = value

    if second_value is None:
        return [min_value] * k

    result = [min_value, second_value] * (k // 2)
    if k % 2:
        result.append(min_value)
    return result
