from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers

        parsed_events = []
        for event in events:
            timestamp = int(event[1])
            if event[0] == "OFFLINE":
                user_id = int(event[2])
                parsed_events.append((timestamp, 0, user_id))
            else:
                parsed_events.append((timestamp, 1, event[2]))

        # Process by timestamp. At the same timestamp, status changes
        # (OFFLINE events) must be processed before MESSAGE events.
        parsed_events.sort(key=lambda x: (x[0], x[1]))

        # offline_until[i] is the first time when user i becomes online again.
        offline_until = [0] * numberOfUsers

        i = 0
        n = len(parsed_events)

        while i < n:
            timestamp = parsed_events[i][0]

            # Process OFFLINE events at this timestamp first.
            while i < n and parsed_events[i][0] == timestamp and parsed_events[i][1] == 0:
                user_id = parsed_events[i][2]
                if offline_until[user_id] <= timestamp:
                    offline_until[user_id] = timestamp + 60
                i += 1

            # Then process MESSAGE events at this timestamp.
            while i < n and parsed_events[i][0] == timestamp and parsed_events[i][1] == 1:
                mentions_string = parsed_events[i][2]

                for token in mentions_string.split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if offline_until[user] <= timestamp:
                                mentions[user] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

                i += 1

        return mentions
