class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            subs = set()
            subs.add("")
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.add(x[i:j])
            return sorted(subs, key=len, reverse=True)

        s_parts = get_substrings(s)
        t_parts = get_substrings(t)

        ans = 0
        total = len(s) + len(t)

        for left in s_parts:
            left_len = len(left)
            if left_len + len(t) <= ans:
                break

            for right in t_parts:
                right_len = len(right)
                if left_len + right_len <= ans:
                    break

                candidate = left + right
                if candidate == candidate[::-1]:
                    ans = left_len + right_len
                    if ans == total:
                        return ans

        return ans
