def magic_square_test(matrix):
    """
    Return True if matrix is a magic square.

    A magic square is a square matrix whose rows, columns, and two main
    diagonals all have the same sum. For order greater than one, the
    entries are required to be distinct, as in the usual definition.
    """
    try:
        rows = [list(row) for row in matrix]
    except TypeError:
        return False

    n = len(rows)
    if n == 0:
        return False

    if any(len(row) != n for row in rows):
        return False

    try:
        target = sum(rows[0])

        if any(sum(row) != target for row in rows):
            return False

        for col in range(n):
            if sum(row[col] for row in rows) != target:
                return False

        if sum(rows[i][i] for i in range(n)) != target:
            return False

        if sum(rows[i][n - 1 - i] for i in range(n)) != target:
            return False
    except TypeError:
        return False

    if n > 1:
        seen = set()
        for row in rows:
            for value in row:
                try:
                    if value in seen:
                        return False
                    seen.add(value)
                except TypeError:
                    return False

    return True


